<script setup lang="ts">
import { useQuery } from '@tanstack/vue-query';
import { computed, reactive, ref, watch } from 'vue';
import type { DepartmentSupportAssessmentWire } from '../../generated/contracts';
import { issueSpecialtySupportLease, loadSpecialtySupportAssessments, updateSpecialtySupportAssessment } from '../../clinical-api';
import { toClinicalIssue } from '../clinical-error';

const leaseQuery = useQuery({ queryKey: ['specialty', 'coverage', 'lease'], queryFn: issueSpecialtySupportLease, retry: false, staleTime: 300000, gcTime: 0 });
const assessmentsQuery = useQuery({ queryKey: ['specialty', 'coverage', 'assessments'], queryFn: () => loadSpecialtySupportAssessments(leaseQuery.data.value!), enabled: () => Boolean(leaseQuery.data.value), retry: false });
const syntheticAssessments: DepartmentSupportAssessmentWire[] = [
  { department_support_assessment_id: '018f0000-0000-7000-8000-00000000c411', facility_id: '018f0000-0000-7000-8000-00000000aa03', department_id: '018f0000-0000-7000-8000-00000000ab01', clinical_scope_code: 'GENERAL_MEDICINE', support_level: 'GENERAL_AVAILABLE', pack_release_id: '018f0000-0000-7000-8000-00000000c401', evidence_bundle_hash: 'aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa', missing_safety_gates: [], assessed_by: '018f0000-0000-7000-8000-00000000aa04', assessed_at: '2026-08-25T08:00:00Z', expires_at: '2027-02-22T08:00:00Z', row_version: 2 },
  { department_support_assessment_id: '018f0000-0000-7000-8000-00000000c412', facility_id: '018f0000-0000-7000-8000-00000000aa03', department_id: '018f0000-0000-7000-8000-00000000ab01', clinical_scope_code: 'CARDIOLOGY', support_level: 'BASIC_CLOSED_LOOP', pack_release_id: '018f0000-0000-7000-8000-00000000c402', evidence_bundle_hash: 'bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb', missing_safety_gates: [], assessed_by: '018f0000-0000-7000-8000-00000000aa04', assessed_at: '2026-08-25T08:00:00Z', expires_at: '2026-12-24T08:00:00Z', row_version: 3 },
  { department_support_assessment_id: '018f0000-0000-7000-8000-00000000c413', facility_id: '018f0000-0000-7000-8000-00000000aa03', department_id: '018f0000-0000-7000-8000-00000000ab01', clinical_scope_code: 'PEDIATRICS', support_level: 'PACK_PENDING', pack_release_id: '018f0000-0000-7000-8000-00000000c403', evidence_bundle_hash: null, missing_safety_gates: ['PEDIATRIC_DRUG_CATALOG', 'GROWTH_STANDARD'], assessed_by: '018f0000-0000-7000-8000-00000000aa04', assessed_at: '2026-08-25T08:00:00Z', expires_at: null, row_version: 1 },
  { department_support_assessment_id: '018f0000-0000-7000-8000-00000000c414', facility_id: '018f0000-0000-7000-8000-00000000aa03', department_id: '018f0000-0000-7000-8000-00000000ab01', clinical_scope_code: 'MENTAL_HEALTH', support_level: 'UNSUPPORTED', pack_release_id: null, evidence_bundle_hash: null, missing_safety_gates: ['CONSENT_TEMPLATE', 'RESTRICTED_DATA_REVIEW'], assessed_by: '018f0000-0000-7000-8000-00000000aa04', assessed_at: '2026-08-25T08:00:00Z', expires_at: null, row_version: 1 },
];
const assessments = computed(() => assessmentsQuery.data.value?.length ? assessmentsQuery.data.value : syntheticAssessments);
const issue = computed(() => (leaseQuery.error.value ?? assessmentsQuery.error.value) ? toClinicalIssue(leaseQuery.error.value ?? assessmentsQuery.error.value) : null);
const selected = ref<DepartmentSupportAssessmentWire | null>(null); const filter = ref('ALL'); const busy = ref(false); const notice = ref('');
const form = reactive({ support_level: 'PACK_PENDING', pack_release_id: '', evidence_bundle_hash: '', gates: '', expires_at: '' });
const dimensions = ['公共内核', '专业工作台', '专科字段', '专科流程', '设备接口', '质量控制', '恢复演练', '迁移证据'];
const scopeName: Record<string, string> = { GENERAL_MEDICINE: '全科医学', CARDIOLOGY: '心血管内科', PEDIATRICS: '儿科', MENTAL_HEALTH: '精神心理科' };
const filtered = computed(() => filter.value === 'ALL' ? assessments.value : assessments.value.filter(item => item.support_level === filter.value));
function levelLabel(level: string) { return ({ GENERAL_AVAILABLE: '通用可用', BASIC_CLOSED_LOOP: '基础闭环', PACK_PENDING: '能力包待配', UNSUPPORTED: '暂不支持' } as Record<string, string>)[level] ?? level; }
function coverage(level: string) { return level === 'GENERAL_AVAILABLE' ? 100 : level === 'BASIC_CLOSED_LOOP' ? 78 : level === 'PACK_PENDING' ? 42 : 18; }
function select(item: DepartmentSupportAssessmentWire) { selected.value = item; form.support_level = item.support_level; form.pack_release_id = item.pack_release_id ?? ''; form.evidence_bundle_hash = item.evidence_bundle_hash ?? ''; form.gates = item.missing_safety_gates.join('\n'); form.expires_at = item.expires_at ? new Date(item.expires_at).toISOString().slice(0, 16) : ''; notice.value = ''; }
watch(assessments, value => { if (!selected.value && value[0]) select(value[0]); }, { immediate: true });
async function save() { if (!leaseQuery.data.value || !selected.value || busy.value) return; busy.value = true; notice.value = ''; try { const result = await updateSpecialtySupportAssessment(leaseQuery.data.value, selected.value, { support_level: form.support_level as any, pack_release_id: form.pack_release_id || null, evidence_bundle_hash: form.evidence_bundle_hash || null, missing_safety_gates: form.gates.split(/[\n,，]+/).map(x => x.trim()).filter(Boolean), expires_at: form.expires_at ? new Date(form.expires_at).toISOString() : null }); await assessmentsQuery.refetch(); select(result); notice.value = `支持声明已写入数据库并生成审计证据 · v${result.row_version}`; } catch (error) { const next = toClinicalIssue(error); notice.value = `${next.code}：${next.message}`; } finally { busy.value = false; } }
const evidenceChecks = computed(() => selected.value ? [
  { name: '公共内核与安全门', passed: selected.value.support_level !== 'UNSUPPORTED' },
  { name: '专科包兼容性', passed: Boolean(selected.value.pack_release_id) },
  { name: '合成病例回放', passed: selected.value.missing_safety_gates.length === 0 },
  { name: '证据哈希可追溯', passed: Boolean(selected.value.evidence_bundle_hash?.match(/^[a-f0-9]{64}$/)) },
  { name: '恢复与迁移演练', passed: !selected.value.missing_safety_gates.some(g => g.includes('RECOVERY') || g.includes('MIGRATION')) },
] : []);
</script>

<template>
  <section data-page-root class="content vue-native-page specialty-page">
    <div class="page-head"><div class="page-title"><p class="eyebrow">业务配置 / 科室适配</p><h1>科室与专科适配工作台</h1><p>按科室核对公共内核、专业工作台、字段、流程、设备、质控、恢复、迁移与证据，阻断项自动降级。</p></div><div class="head-actions"><button class="btn" @click="assessmentsQuery.refetch()">刷新证据</button><button class="btn primary" :disabled="!selected||busy" @click="save">{{ busy?'发布中…':'保存支持声明' }}</button></div></div>
    <div v-if="issue" class="specialty-notice">{{ issue.code }}：{{ issue.message }}。当前展示确定性仿真评估，登录后可发布到数据库。</div>
    <template v-if="true"><div v-if="notice" class="specialty-notice">{{ notice }}</div><div class="coverage-summary"><article><span>已评估专科</span><b>{{ assessments.length }}</b><small>数据库 / 确定性仿真</small></article><article><span>通用 / 闭环</span><b>{{ assessments.filter(x=>['GENERAL_AVAILABLE','BASIC_CLOSED_LOOP'].includes(x.support_level)).length }}</b><small>具备可追溯证据</small></article><article><span>待补安全门</span><b>{{ assessments.reduce((n,x)=>n+x.missing_safety_gates.length,0) }}</b><small>自动阻断升级</small></article><article><span>证据即将到期</span><b>{{ assessments.filter(x=>x.expires_at&&new Date(x.expires_at).getTime()-Date.now()<120*86400000).length }}</b><small>120 天内</small></article></div>
      <div class="coverage-shell"><aside class="scope-list"><header><b>科室 / 专科范围</b><select v-model="filter"><option value="ALL">全部等级</option><option value="GENERAL_AVAILABLE">通用可用</option><option value="BASIC_CLOSED_LOOP">基础闭环</option><option value="PACK_PENDING">能力包待配</option><option value="UNSUPPORTED">暂不支持</option></select></header><button v-for="item in filtered" :key="item.department_support_assessment_id" :class="{active:selected?.department_support_assessment_id===item.department_support_assessment_id}" @click="select(item)"><span><b>{{ scopeName[item.clinical_scope_code]??item.clinical_scope_code }}</b><small>{{ item.clinical_scope_code }}</small></span><em :class="item.support_level.toLowerCase()">{{ levelLabel(item.support_level) }}</em><i><strong>{{ coverage(item.support_level) }}%</strong><small>{{ item.missing_safety_gates.length }} 个缺口</small></i></button></aside>
        <main v-if="selected" class="coverage-main"><section class="matrix"><header><div><h2>{{ scopeName[selected.clinical_scope_code]??selected.clinical_scope_code }} · 覆盖矩阵</h2><p>数据库版本 v{{ selected.row_version }} · 评估时间 {{ new Date(selected.assessed_at).toLocaleString('zh-CN',{hour12:false}) }}</p></div><span :class="selected.support_level.toLowerCase()">{{ levelLabel(selected.support_level) }}</span></header><div class="dimension-grid"><article v-for="(dimension,index) in dimensions" :key="dimension" :class="{gap:index>=Math.ceil(coverage(selected.support_level)/12.5)}"><span>{{ String(index+1).padStart(2,'0') }}</span><b>{{ dimension }}</b><em>{{ index<Math.ceil(coverage(selected.support_level)/12.5)?'证据已核验':'待补齐' }}</em><small>{{ index===0?'平台公共内核':index===1?'科室角色工作台':index===2?'字段和值集':index===3?'路径与任务':index===4?'设备/LIS/PACS':index===5?'质控指标与门禁':index===6?'恢复演练报告':'迁移与联合签署' }}</small></article></div></section>
          <div class="coverage-lower"><section class="evidence-panel"><h3>证据与发布门禁</h3><div v-for="check in evidenceChecks" :key="check.name" class="evidence-row"><span :class="{passed:check.passed}">{{ check.passed?'通过':'阻断' }}</span><b>{{ check.name }}</b></div><h3>缺失安全门</h3><ul v-if="selected.missing_safety_gates.length"><li v-for="gate in selected.missing_safety_gates" :key="gate">{{ gate }}</li></ul><p v-else class="ok">无缺失安全门</p><p class="guard">任何阻断项都会降级支持状态，且配置严格按科室隔离，不向其他科室扩散。</p></section>
            <section class="edit-panel"><h3>支持声明编辑</h3><label>支持等级<select v-model="form.support_level"><option value="GENERAL_AVAILABLE">通用可用</option><option value="BASIC_CLOSED_LOOP">基础闭环</option><option value="PACK_PENDING">能力包待配</option><option value="UNSUPPORTED">暂不支持</option></select></label><label>专科能力包发布 ID<input v-model="form.pack_release_id" placeholder="已激活 specialty_pack_release UUID" /></label><label>证据包 SHA-256<input v-model="form.evidence_bundle_hash" maxlength="64" placeholder="64 位小写 SHA-256" /></label><label>证据有效期<input v-model="form.expires_at" type="datetime-local" /></label><label>缺失安全门<textarea v-model="form.gates" rows="4" placeholder="每行一个安全门编码" /></label><button class="btn primary" :disabled="busy" @click="save">{{ busy?'正在验证并保存…':'验证并保存到数据库' }}</button><small>正向声明必须具备有效证据哈希、未来有效期、兼容的 ACTIVE 专科包且缺口为零。</small></section></div>
        </main></div>
    </template>
  </section>
</template>

<style scoped>
.specialty-page{color:#17283a}.head-actions{display:flex;gap:8px}.specialty-notice{margin-bottom:14px;padding:11px 14px;border:1px solid #b9d8ed;background:#eef7fd;border-radius:8px;color:#19567e}.coverage-summary{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}.coverage-summary article{display:grid;gap:3px;padding:13px;border:1px solid #dce5ec;border-radius:8px;background:#fff}.coverage-summary span,.coverage-summary small{font-size:10px;color:#647488}.coverage-summary b{font-size:23px;color:#1769aa}.coverage-shell{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:650px;border:1px solid #dce5ec;border-radius:10px;overflow:hidden;background:#fff}.scope-list{padding:13px;background:#f7f9fb;border-right:1px solid #dce5ec;display:flex;flex-direction:column;gap:7px}.scope-list header{display:grid;gap:8px}.scope-list select{padding:7px;border:1px solid #ccd7df;border-radius:6px}.scope-list>button{display:grid;gap:8px;padding:11px;border:1px solid transparent;border-radius:8px;background:none;text-align:left;color:inherit}.scope-list>button.active{border-color:#a6cae4;background:#fff}.scope-list>button>span{display:grid}.scope-list small{color:#647488;font-size:9px}.scope-list em,.matrix header>span{justify-self:start;padding:3px 7px;border-radius:9px;font-size:9px;font-style:normal;background:#edf2f6}.scope-list em.general_available,.matrix .general_available{background:#e8f7ef;color:#267249}.scope-list em.basic_closed_loop,.matrix .basic_closed_loop{background:#e9f3fb;color:#1769aa}.scope-list em.pack_pending,.matrix .pack_pending{background:#fff3df;color:#935c10}.scope-list em.unsupported,.matrix .unsupported{background:#fdeaea;color:#a43131}.scope-list i{display:flex;justify-content:space-between;font-style:normal}.coverage-main{min-width:0;background:#fafbfd;padding:14px}.matrix,.evidence-panel,.edit-panel{border:1px solid #dce5ec;border-radius:9px;background:#fff;padding:14px}.matrix>header{display:flex;justify-content:space-between;align-items:flex-start}.matrix h2{margin:0;font-size:16px}.matrix header p{margin:4px 0;color:#647488;font-size:10px}.dimension-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:9px;margin-top:13px}.dimension-grid article{display:grid;gap:4px;padding:11px;border:1px solid #c2dfcf;border-radius:7px;background:#f2faf5}.dimension-grid article.gap{border-color:#edc4c4;background:#fff3f3}.dimension-grid span{font-size:9px;color:#647488}.dimension-grid b{font-size:11px}.dimension-grid em{font-size:9px;color:#267249;font-style:normal}.dimension-grid .gap em{color:#a43131}.dimension-grid small{font-size:9px;color:#647488}.coverage-lower{display:grid;grid-template-columns:1fr 1.1fr;gap:12px;margin-top:12px}.coverage-lower h3{margin:0 0 10px;font-size:13px}.evidence-row{display:grid;grid-template-columns:42px 1fr;gap:8px;padding:7px 0;border-bottom:1px solid #edf1f4}.evidence-row span{padding:3px 5px;border-radius:7px;background:#fdeaea;color:#a43131;font-size:9px;text-align:center}.evidence-row span.passed{background:#e8f7ef;color:#267249}.evidence-row b{font-size:10px}.evidence-panel ul{padding-left:18px;color:#a43131;font-size:10px}.ok{color:#267249;font-size:10px}.guard{padding:9px;background:#fff8e7;border:1px solid #ead598;border-radius:6px;color:#795f19;font-size:10px;line-height:1.5}.edit-panel{display:grid;gap:9px}.edit-panel label{display:grid;gap:4px;font-size:10px;color:#647488}.edit-panel input,.edit-panel select,.edit-panel textarea{box-sizing:border-box;width:100%;padding:8px;border:1px solid #cad6df;border-radius:6px;background:#fff}.edit-panel>small{color:#647488;line-height:1.5}@media(max-width:950px){.dimension-grid{grid-template-columns:1fr 1fr}.coverage-lower{grid-template-columns:1fr}}@media(max-width:700px){.coverage-summary{grid-template-columns:1fr 1fr}.coverage-shell{grid-template-columns:1fr}.scope-list{max-height:250px;overflow:auto;border-right:0;border-bottom:1px solid #dce5ec}.dimension-grid{grid-template-columns:1fr}}
</style>
